def meals():
    out = []
    for n in (19, 20, 21):
        out.append('7:%d ' % n + '; '.join("'%s' ('%s', %s)" % (tr, ar, ', '.join(it)) for tr, ar, it in SEG[n]))
    return tuple(out)
